      gap: 1.5rem;
      z-index: 999;
      box-shadow: 0 -10px 30px rgba(0, 0, 0, 0.6);
      animation: slideUp 0.3s ease;
    }

    @keyframes slideUp {
      from { transform: translateY(100%); }
      to { transform: translateY(0); }
    }

    .player-track-info {
      display: flex;
      align-items: center;
      gap: 1rem;
      min-width: 200px;
      max-width: 280px;
    }

    .player-cover {
      width: 44px;
      height: 44px;
      border-radius: 10px;
      background: linear-gradient(135deg, var(--primary) 0%, var(--secondary) 100%);
      display: flex;
      align-items: center;
      justify-content: center;
      color: #fff;
      font-size: 1.2rem;
      flex-shrink: 0;
    }

    .player-titles h4 {
      font-size: 0.85rem;
      font-weight: 800;
      color: #fff;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }

    .player-titles p {
      font-size: 0.72rem;
      color: var(--text-muted);
    }

    .player-controls-center {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 0.4rem;
      flex: 1;
      max-width: 550px;
    }

    .player-buttons {
      display: flex;
      align-items: center;
      gap: 1rem;
    }

    .btn-player-ctrl {
      background: none;
      border: none;
      color: var(--text-muted);
      font-size: 1rem;
      cursor: pointer;
      transition: all 0.2s;
    }

    .btn-player-ctrl:hover {
      color: #fff;
      transform: scale(1.1);
    }

    .btn-play-pause {
      width: 42px;
      height: 42px;
      border-radius: 50%;
      background: #fff;
      color: #0a0914;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.1rem;
      cursor: pointer;
      border: none;
      box-shadow: 0 4px 15px rgba(255, 255, 255, 0.3);
      transition: all 0.2s;
    }

    .btn-play-pause:hover {
      transform: scale(1.08);
      background: var(--secondary);
    }

    .player-progress-area {
      width: 100%;
      display: flex;
      align-items: center;
      gap: 0.75rem;
      font-size: 0.72rem;
      color: var(--text-muted);
    }

    .player-progress-bar {
      flex: 1;
      height: 5px;
      background: rgba(255, 255, 255, 0.1);
      border-radius: 10px;
      cursor: pointer;
      position: relative;
      overflow: hidden;
    }

    .player-progress-filled {
      height: 100%;
      width: 0%;
      background: linear-gradient(90deg, var(--primary) 0%, var(--secondary) 100%);
      border-radius: 10px;
    }

    .player-options-right {
      display: flex;
      align-items: center;
      gap: 1rem;
      min-width: 180px;
      justify-content: flex-end;
    }

    .btn-speed-toggle {
      background: rgba(255, 255, 255, 0.08);
      border: 1px solid var(--panel-border);
      color: #fff;
      font-size: 0.72rem;
      font-weight: 800;
      padding: 3px 8px;
      border-radius: 6px;
      cursor: pointer;
    }

    .player-volume-wrapper {
      display: flex;
      align-items: center;
      gap: 0.4rem;
      color: var(--text-muted);
    }

    .player-volume-slider {
      width: 70px;
      accent-color: var(--secondary);
      cursor: pointer;
    }

    .btn-close-player {
      background: none;
      border: none;
      color: var(--text-muted);
      cursor: pointer;
      font-size: 1rem;
    }

    .btn-close-player:hover { color: var(--danger); }

    /* FLOATING AI CHATBOT WIDGET */
    .chat-widget {
      position: fixed;
      bottom: 6.5rem;
      right: 2rem;
      z-index: 1000;
      display: flex;
      flex-direction: column;
      align-items: flex-end;
    }

    .chat-toggle {
      width: 58px;
      height: 58px;
      border-radius: 50%;
      background: linear-gradient(135deg, var(--primary) 0%, #ec4899 100%);
      box-shadow: 0 8px 25px var(--primary-glow);
      display: flex;
      align-items: center;
      justify-content: center;
      color: white;
      font-size: 1.4rem;
      cursor: pointer;
      transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
      border: none;
      position: relative;
    }

    .chat-toggle:hover {
      transform: scale(1.1) rotate(5deg);
    }

    .chat-online-dot {
      width: 12px;
      height: 12px;
      border-radius: 50%;
      background: var(--secondary);
      border: 2px solid var(--bg-dark);
      position: absolute;
      top: 0;
      right: 0;
    }

    .chat-window {
      width: 390px;
      height: 520px;
      background: rgba(18, 16, 32, 0.96);
      backdrop-filter: blur(25px);
      -webkit-backdrop-filter: blur(25px);
      border: 1px solid var(--panel-border-hover);
      border-radius: 24px;
      box-shadow: 0 20px 50px rgba(0, 0, 0, 0.7);
      display: flex;
      flex-direction: column;
      overflow: hidden;
      margin-bottom: 1rem;
      transform: translateY(20px) scale(0.9);
      opacity: 0;
      pointer-events: none;
      transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    }

    .chat-window.active {
      transform: translateY(0) scale(1);
      opacity: 1;
      pointer-events: auto;
    }

    .chat-header {
      padding: 1rem 1.25rem;
      background: linear-gradient(135deg, rgba(139, 92, 246, 0.3) 0%, rgba(236, 72, 153, 0.2) 100%);
      border-bottom: 1px solid var(--panel-border);
      display: flex;
      justify-content: space-between;
      align-items: center;
    }

    .chat-header-info {
      display: flex;
      align-items: center;
      gap: 0.6rem;
    }

    .chat-header-info h4 {
      font-size: 0.95rem;
      font-weight: 800;
      color: #fff;
    }

    .chat-header-info span {
      font-size: 0.7rem;
      color: var(--secondary);
      font-weight: 700;
    }

    .chat-header-close {
      background: none;
      border: none;
      color: var(--text-muted);
      cursor: pointer;
      font-size: 1.1rem;
    }

    .chat-header-close:hover { color: #fff; }

    .chat-messages {
      flex: 1;
      padding: 1.2rem;
      overflow-y: auto;
      display: flex;
      flex-direction: column;
      gap: 0.85rem;
      font-size: 0.82rem;
    }

    .chat-bubble {
      max-width: 85%;
      padding: 0.7rem 0.95rem;
      border-radius: 14px;
      line-height: 1.5;
      word-break: break-word;
    }

    .chat-bubble.bot {
      background: rgba(255, 255, 255, 0.06);
      border: 1px solid var(--panel-border);
      color: #f1f5f9;
      align-self: flex-start;
      border-bottom-left-radius: 4px;
    }

    .chat-bubble.user {
      background: linear-gradient(135deg, var(--primary) 0%, var(--primary-hover) 100%);
      color: #fff;
      align-self: flex-end;
      border-bottom-right-radius: 4px;
      box-shadow: 0 4px 15px var(--primary-glow);
    }

    .chat-quick-suggestions {
      padding: 0.5rem 1rem;
      display: flex;
      gap: 0.4rem;
      overflow-x: auto;
      border-top: 1px solid var(--panel-border);
      background: rgba(10, 9, 20, 0.5);
    }

    .suggestion-chip {
      background: rgba(255, 255, 255, 0.04);
      border: 1px solid var(--panel-border);
      color: var(--text-muted);
      font-size: 0.72rem;
      padding: 3px 8px;
      border-radius: 12px;
      white-space: nowrap;
      cursor: pointer;
      transition: all 0.2s;
    }

    .suggestion-chip:hover {
      border-color: var(--primary);
      color: #fff;
    }

    .chat-input-area {
      display: flex;
      padding: 0.85rem 1rem;
      border-top: 1px solid var(--panel-border);
      background: rgba(10, 9, 20, 0.9);
      gap: 0.6rem;
    }

    .chat-input {
      flex: 1;
      background: rgba(255, 255, 255, 0.05);
      border: 1px solid var(--panel-border);
      border-radius: 12px;
      padding: 0.65rem 0.9rem;
      color: #fff;
      font-size: 0.82rem;
      outline: none;
      transition: all 0.25s;
    }

    .chat-input:focus {
      border-color: var(--primary);
      background: rgba(139, 92, 246, 0.06);
    }

    .chat-send-btn {
      background: var(--primary);
      border: none;
      color: #fff;
      width: 38px;
      height: 38px;
      border-radius: 10px;
      display: flex;
      align-items: center;
      justify-content: center;
      cursor: pointer;
      transition: all 0.2s;
    }

    .chat-send-btn:hover {
      background: var(--primary-hover);
      transform: scale(1.05);
    }

    /* MODAL BASE STYLES */
    .modal-overlay {
      display: none;
      position: fixed;
      inset: 0;
      background: rgba(0, 0, 0, 0.85);
      backdrop-filter: blur(16px);
      -webkit-backdrop-filter: blur(16px);
      z-index: 2000;
      align-items: center;
      justify-content: center;
      padding: 1.5rem;
      animation: fadeIn 0.25s ease;
    }

    @keyframes fadeIn {
      from { opacity: 0; }
      to { opacity: 1; }
    }

    .modal-box {
      background: rgba(20, 18, 35, 0.98);
      border: 1px solid var(--panel-border-hover);
      border-radius: 24px;
      width: 100%;
      max-width: 600px;
      max-height: 90vh;
      overflow-y: auto;
      box-shadow: 0 25px 60px rgba(0, 0, 0, 0.8);
      display: flex;
      flex-direction: column;
    }

    .modal-header {
      padding: 1.25rem 1.75rem;
      border-bottom: 1px solid var(--panel-border);
      display: flex;
      justify-content: space-between;
      align-items: center;
    }

    .modal-header h3 {
      font-size: 1.15rem;
      font-weight: 800;
      color: #fff;
    }

    .modal-close-btn {
      background: none;
      border: none;
      color: var(--text-muted);
      cursor: pointer;
      font-size: 1.25rem;
    }

    .modal-close-btn:hover { color: #fff; }

    .modal-body {
      padding: 1.75rem;
    }

    /* FORM ELEMENTS */
    .form-group {
      margin-bottom: 1.2rem;
    }

    .form-group label {
      display: block;
      font-size: 0.78rem;
      font-weight: 700;
      color: var(--text-muted);
      margin-bottom: 0.4rem;
    }

    .form-control {
      width: 100%;
      padding: 0.75rem 1rem;
      background: rgba(255, 255, 255, 0.04);
      border: 1px solid var(--panel-border);
      border-radius: 12px;
      color: #fff;
      font-size: 0.85rem;
      outline: none;
      transition: all 0.25s;
    }

    .form-control:focus {
      border-color: var(--primary);
      background: rgba(139, 92, 246, 0.06);
    }

    textarea.form-control {
      resize: vertical;
      min-height: 80px;
    }

    .file-dropzone {
      border: 2px dashed var(--panel-border);
      border-radius: 14px;
      padding: 1.5rem;
      text-align: center;
      cursor: pointer;
      transition: all 0.25s;
      background: rgba(255, 255, 255, 0.02);
    }

    .file-dropzone:hover {
      border-color: var(--primary);
      background: rgba(139, 92, 246, 0.05);
    }

    .file-dropzone i {
      font-size: 2rem;
      color: var(--primary);
      margin-bottom: 0.5rem;
    }

    .file-dropzone p {
      font-size: 0.8rem;
      color: var(--text-muted);
    }

    .file-dropzone span {
      font-size: 0.72rem;
      color: var(--secondary);
      font-weight: 700;
    }

    .btn-submit-modal {
      width: 100%;
      padding: 0.85rem;
      background: linear-gradient(135deg, var(--primary) 0%, var(--primary-hover) 100%);
      color: #fff;
      border: none;
      border-radius: 12px;
      font-size: 0.9rem;
      font-weight: 800;
      cursor: pointer;
      box-shadow: 0 4px 15px var(--primary-glow);
      transition: all 0.25s;
      margin-top: 0.5rem;
    }

    .btn-submit-modal:hover {
      transform: translateY(-2px);
      box-shadow: 0 8px 25px var(--primary-glow);
    }

    /* READER MODAL */
    .reader-modal-box {
      max-width: 1000px;
      height: 90vh;
    }

    .reader-tabs {
      display: flex;
      gap: 0.5rem;
    }

    .reader-tab-btn {
      background: rgba(255, 255, 255, 0.05);
      border: 1px solid var(--panel-border);
      color: var(--text-muted);
      font-size: 0.78rem;
      font-weight: 700;
      padding: 0.4rem 0.9rem;
      border-radius: 8px;
      cursor: pointer;
    }

    .reader-tab-btn.active {
      background: var(--secondary);
      color: #0a0914;
      border-color: var(--secondary);
    }

    .reader-content-frame {
      flex: 1;
      width: 100%;
      height: 100%;
      border: none;
    }

    .reader-text-container {
      display: none;
      flex: 1;
      overflow-y: auto;
      padding: 2rem;
      line-height: 1.8;
      font-size: 1.05rem;
      color: #e2e8f0;
      white-space: pre-wrap;
    }

    /* TOAST ALERTS */
    .toast-container {
      position: fixed;
      top: 1.5rem;
      right: 1.5rem;
      z-index: 3000;
      display: flex;
      flex-direction: column;
      gap: 0.75rem;
      pointer-events: none;
    }

    .toast {
      pointer-events: auto;
      min-width: 280px;
      max-width: 380px;
      padding: 0.85rem 1.25rem;
      border-radius: 12px;
      background: rgba(20, 18, 35, 0.96);
      border: 1px solid var(--panel-border);
      backdrop-filter: blur(16px);
      box-shadow: 0 10px 30px rgba(0, 0, 0, 0.6);
      display: flex;
      align-items: center;
      gap: 0.75rem;
      font-size: 0.82rem;
      animation: toastSlideIn 0.3s ease;
    }

    @keyframes toastSlideIn {
      from { transform: translateX(100%); opacity: 0; }
      to { transform: translateX(0); opacity: 1; }
    }

    .toast.success { border-color: var(--success); color: #34d399; }
    .toast.error { border-color: var(--danger); color: #f87171; }
    .toast.info { border-color: var(--primary); color: #c4b5fd; }

    /* AUTH MODAL TABS */
    .auth-tab-row {
      display: flex;
      gap: 0.5rem;
      background: rgba(255, 255, 255, 0.04);
      padding: 4px;
      border-radius: 12px;
      margin-bottom: 1.5rem;
    }

    .auth-tab-btn {
      flex: 1;
      padding: 0.55rem;
      background: none;
      border: none;
      color: var(--text-muted);
      font-size: 0.82rem;
      font-weight: 700;
      border-radius: 8px;
      cursor: pointer;
    }

    .auth-tab-btn.active {
      background: var(--primary);
      color: #fff;
    }

    /* RESPONSIVE BREAKPOINTS */
    @media (max-width: 768px) {
      header { padding: 0.85rem 1rem; }
      .header-search { display: none; }
      .books-grid { grid-template-columns: 1fr; }
      .audio-player-bar {
        flex-direction: column;
        padding: 0.85rem 1rem;
        gap: 0.75rem;
      }
      .player-track-info { max-width: 100%; width: 100%; }
      .player-options-right { display: none; }
      .chat-window { width: calc(100vw - 2rem); right: 1rem; }
    }
  </style>
</head>
<body>

  <!-- TOAST NOTIFICATION CONTAINER -->
  <div class="toast-container" id="toastContainer"></div>

  <!-- NAVIGATION HEADER -->
  <header>
    <a href="/" class="brand">
      <div class="brand-logo-icon">
        <i class="fa-solid fa-graduation-cap"></i>
      </div>
      <div class="brand-text">
        <h1>SmartLibrary</h1>
        <span>AI & Audio Kutubxona</span>
      </div>
    </a>

    <!-- SEARCH BAR -->
    <div class="header-search">
      <i class="fa-solid fa-magnifying-glass"></i>
      <input type="text" id="searchInput" placeholder="Kitob, muallif yoki janr qidiring..." oninput="handleSearch()">
    </div>

    <!-- ACTIONS / USER BADGE -->
    <div class="header-actions">
      <!-- Unauthenticated State -->
      <button class="btn-nav btn-nav-primary" id="btnOpenAuth" onclick="openAuthModal('login')">
        <i class="fa-solid fa-right-to-bracket"></i> Kirish
      </button>

      <!-- Authenticated State -->
      <div class="user-pill" id="userPill" style="display: none;">
        <i class="fa-solid fa-user-circle" style="color: var(--primary); font-size: 1.1rem;"></i>
        <span id="headerUsername" style="font-weight: 700;">Foydalanuvchi</span>
        <span class="user-role-badge user" id="headerRoleBadge">Kitobxon</span>
      </div>

      <button class="btn-nav btn-nav-secondary" id="btnLogout" style="display: none;" onclick="logout()">
        <i class="fa-solid fa-right-from-bracket"></i> Chiqish
      </button>
    </div>
  </header>

  <!-- MAIN VIEW -->
  <main class="main-container">

    <!-- HERO METRICS -->
    <section class="hero-stats-grid">
      <div class="stat-card">
        <div class="stat-icon books"><i class="fa-solid fa-book"></i></div>
        <div class="stat-data">
          <h3 id="statTotalBooks">0</h3>
          <p>Kutubxona fondi</p>
        </div>
      </div>
      <div class="stat-card">
        <div class="stat-icon audio"><i class="fa-solid fa-headphones"></i></div>
        <div class="stat-data">
          <h3 id="statTotalAudio">0</h3>
          <p>Audio kitoblar</p>
        </div>
      </div>
      <div class="stat-card">
        <div class="stat-icon genres"><i class="fa-solid fa-shapes"></i></div>
        <div class="stat-data">
          <h3 id="statTotalGenres">0</h3>
          <p>Turkum & Janrlar</p>
        </div>
      </div>
      <div class="stat-card">
        <div class="stat-icon ai"><i class="fa-solid fa-wand-magic-sparkles"></i></div>
        <div class="stat-data">
          <h3>24/7 AI</h3>
          <p>Kutubxonachi faol</p>
        </div>
      </div>
    </section>

    <!-- ADMIN ACTION TOOLBAR (ONLY FOR ADMIN) -->
    <section class="admin-toolbar" id="adminToolbar">
      <div class="admin-toolbar-title">
        <i class="fa-solid fa-shield-halved"></i>
        <span>Admin Boshqaruv Paneli (Faqat Admin huquqi)</span>
      </div>
      <div class="admin-toolbar-btns">
        <button class="btn-nav btn-nav-primary" onclick="openAddBookModal()">
          <i class="fa-solid fa-plus"></i> Yangi Kitob Qo'shish
        </button>
        <button class="btn-nav btn-nav-secondary" onclick="document.getElementById('quickPdfInput').click()">
          <i class="fa-solid fa-file-pdf" style="color:#f87171;"></i> PDF Yuklash
        </button>
        <button class="btn-nav btn-nav-secondary" onclick="document.getElementById('quickZipInput').click()">
          <i class="fa-solid fa-file-zipper" style="color:var(--secondary);"></i> ZIP Arxiv
        </button>
        <input type="file" id="quickPdfInput" accept=".pdf" style="display:none;" onchange="handleQuickUpload(this, 'pdf')">
        <input type="file" id="quickZipInput" accept=".zip" style="display:none;" onchange="handleQuickUpload(this, 'zip')">
      </div>
    </section>

    <!-- GENRE FILTER & AUDIO TOGGLE -->
    <div class="filter-wrapper">
      <div class="genre-pills" id="genrePillsContainer">
        <button class="genre-pill active" onclick="filterByGenre('all', this)">Barchasi</button>
      </div>

      <button class="audio-filter-toggle" id="audioFilterToggle" onclick="toggleAudioOnlyFilter()">
        <i class="fa-solid fa-headphones"></i> Faqat Audio Kitoblar
      </button>
    </div>

    <!-- BOOKS SECTION TITLE -->
    <div class="books-section-title">
      <span id="catalogCountText">Barcha Kitoblar</span>
      <span style="font-size: 0.8rem; color: var(--text-muted); font-weight: 500;" id="searchResultFeedback"></span>
    </div>

    <!-- BOOKS GRID -->
    <div class="books-grid" id="booksGrid">
      <!-- Injected via JavaScript -->
    </div>

  </main>

  <!-- PERSISTENT BOTTOM AUDIO PLAYER BAR -->
  <div class="audio-player-bar" id="audioPlayerBar">
    <!-- Hidden native audio element -->
    <audio id="nativeAudioPlayer" preload="auto"></audio>

    <div class="player-track-info">
      <div class="player-cover">
        <i class="fa-solid fa-headphones"></i>
      </div>
      <div class="player-titles">
        <h4 id="playerBookTitle">Kitob Nomi</h4>
        <p id="playerBookAuthor">Muallif Nomi</p>
      </div>
    </div>

    <div class="player-controls-center">
      <div class="player-buttons">
        <button class="btn-player-ctrl" onclick="seekAudio(-10)" title="10 soniya orqaga">
          <i class="fa-solid fa-rotate-left"></i> 10s
        </button>
        <button class="btn-play-pause" id="btnPlayPause" onclick="togglePlayPause()">
          <i class="fa-solid fa-play" id="playPauseIcon"></i>
        </button>
        <button class="btn-player-ctrl" onclick="seekAudio(10)" title="10 soniya oldinga">
          10s <i class="fa-solid fa-rotate-right"></i>
        </button>
      </div>
      <div class="player-progress-area">
        <span id="playerCurrentTime">00:00</span>
        <div class="player-progress-bar" id="playerProgressBar" onclick="handleSeekbarClick(event)">
          <div class="player-progress-filled" id="playerProgressFilled"></div>
        </div>
        <span id="playerDuration">00:00</span>
      </div>
    </div>

    <div class="player-options-right">
      <button class="btn-speed-toggle" id="btnPlaybackRate" onclick="cyclePlaybackRate()">1.0x</button>
      <div class="player-volume-wrapper">
        <i class="fa-solid fa-volume-high" id="playerVolumeIcon" onclick="toggleMute()"></i>
        <input type="range" class="player-volume-slider" id="playerVolumeSlider" min="0" max="1" step="0.05" value="1" oninput="setVolume(this.value)">
      </div>
      <button class="btn-close-player" onclick="closeAudioPlayer()" title="Yopish">
        <i class="fa-solid fa-xmark"></i>
      </button>
    </div>
  </div>

  <!-- FLOATING AI CHATBOT WIDGET -->
  <div class="chat-widget">
    <div class="chat-window" id="chatWindow">
      <div class="chat-header">
        <div class="chat-header-info">
          <i class="fa-solid fa-robot" style="color: var(--secondary); font-size: 1.2rem;"></i>
          <div>
            <h4>AI Kutubxonachi</h4>
            <span>Doimo faol • Barcha kitoblar bilimdoni</span>
          </div>
        </div>
