  <!-- MODAL: READER (PDF & TEXT VIEW) -->
  <div class="modal-overlay" id="readerModal">
    <div class="modal-box reader-modal-box">
      <div class="modal-header">
        <div style="display:flex; align-items:center; gap:1rem;">
          <h3 id="readerBookTitle" style="color:var(--secondary); font-size: 1rem;">Kitobni O'qish</h3>
          <div class="reader-tabs">
            <button class="reader-tab-btn active" id="btnTabPdf" onclick="switchReaderTab('pdf')">PDF Ko'rish</button>
            <button class="reader-tab-btn" id="btnTabText" onclick="switchReaderTab('text')">Matn Rejimi</button>
          </div>
        </div>
        <button class="modal-close-btn" onclick="closeReaderModal()"><i class="fa-solid fa-xmark"></i></button>
      </div>
      <iframe id="readerPdfFrame" class="reader-content-frame"></iframe>
      <div id="readerTextContainer" class="reader-text-container"></div>
    </div>
