  <!-- JAVASCRIPT LOGIC -->
  <script>
    // GLOBAL STATE
    let allBooks = [];
    let currentFilterGenre = 'all';
    let filterAudioOnly = false;
    let currentUser = null;
    let currentPlaybackRate = 1.0;
    const playbackRates = [0.75, 1.0, 1.25, 1.5, 2.0];

    const nativeAudio = document.getElementById('nativeAudioPlayer');

    // INITIALIZATION
    document.addEventListener('DOMContentLoaded', () => {
      checkAuth();
      loadBooks();
      setupAudioPlayerEvents();
    });

    // TOAST NOTIFICATIONS
    function showToast(message, type = 'info') {
      const container = document.getElementById('toastContainer');
      const toast = document.createElement('div');
      toast.className = `toast ${type}`;

      const icons = {
        success: 'fa-circle-check',
        error: 'fa-circle-exclamation',
        info: 'fa-circle-info'
      };

      toast.innerHTML = `<i class="fa-solid ${icons[type] || 'fa-circle-info'}"></i> <span>${message}</span>`;
      container.appendChild(toast);

      setTimeout(() => {
        toast.style.opacity = '0';
        toast.style.transform = 'translateX(100%)';
        toast.style.transition = 'all 0.3s ease';
        setTimeout(() => toast.remove(), 300);
      }, 4000);
    }

    // AUTHENTICATION & USER STATE
    async function checkAuth() {
      const token = localStorage.getItem('access_token');
      const btnOpenAuth = document.getElementById('btnOpenAuth');
      const userPill = document.getElementById('userPill');
      const btnLogout = document.getElementById('btnLogout');
      const adminToolbar = document.getElementById('adminToolbar');

      if (!token) {
        currentUser = null;
        btnOpenAuth.style.display = 'inline-flex';
        userPill.style.display = 'none';
        btnLogout.style.display = 'none';
        adminToolbar.style.display = 'none';
        renderBooks();
        return;
      }

      try {
        const res = await fetch('/api/auth/me/', {
          headers: { 'Authorization': 'Bearer ' + token }
        });
        if (res.ok) {
          currentUser = await res.json();
          const isAdmin = currentUser.is_staff || currentUser.is_superuser;

          btnOpenAuth.style.display = 'none';
          userPill.style.display = 'flex';
          btnLogout.style.display = 'inline-flex';

          document.getElementById('headerUsername').innerText = currentUser.username || currentUser.email.split('@')[0];
          const roleBadge = document.getElementById('headerRoleBadge');

          if (isAdmin) {
            roleBadge.innerText = 'Admin';
            roleBadge.className = 'user-role-badge admin';
            adminToolbar.style.display = 'flex';
          } else {
            roleBadge.innerText = 'Kitobxon';
            roleBadge.className = 'user-role-badge user';
            adminToolbar.style.display = 'none';
          }
          renderBooks();
        } else {
          logout();
        }
      } catch (e) {
        console.error("Auth check failed:", e);
      }
    }

    function logout() {
      localStorage.removeItem('access_token');
      localStorage.removeItem('refresh_token');
      currentUser = null;
      showToast("Tizimdan chiqildi.", 'info');
      checkAuth();
    }

    function openAuthModal(tab = 'login') {
      switchAuthTab(tab);
      document.getElementById('authModal').style.display = 'flex';
    }

    function closeAuthModal() {
      document.getElementById('authModal').style.display = 'none';
    }

    function switchAuthTab(tab) {
      const tabLogin = document.getElementById('tabAuthLogin');
      const tabRegister = document.getElementById('tabAuthRegister');
      const formLogin = document.getElementById('formLogin');
      const formRegister = document.getElementById('formRegister');
      const title = document.getElementById('authModalTitle');

      if (tab === 'login') {
        tabLogin.classList.add('active');
        tabRegister.classList.remove('active');
        formLogin.style.display = 'block';
        formRegister.style.display = 'none';
        title.innerText = "Tizimga Kirish";
      } else {
        tabRegister.classList.add('active');
        tabLogin.classList.remove('active');
        formLogin.style.display = 'none';
        formRegister.style.display = 'block';
        title.innerText = "Ro'yxatdan O'tish";
      }
    }

    async function handleLoginSubmit(e) {
      e.preventDefault();
      const email = document.getElementById('loginEmail').value.trim();
      const password = document.getElementById('loginPassword').value;
      const btn = document.getElementById('btnLoginSubmit');
      btn.disabled = true;
      btn.innerText = "Kirilmoqda...";

      try {
        const res = await fetch('/api/auth/login/', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ email, password })
        });
        const data = await res.json();
        if (res.ok) {
          localStorage.setItem('access_token', data.access);
          localStorage.setItem('refresh_token', data.refresh);
          showToast("Xush kelibsiz! Tizimga muvaffaqiyatli kirildi.", 'success');
          closeAuthModal();
          await checkAuth();
        } else {
          showToast(data.detail || "Email yoki parol xato kiritildi.", 'error');
        }
      } catch (err) {
        showToast("Server bilan bog'lanishda xatolik yuz berdi.", 'error');
      } finally {
        btn.disabled = false;
        btn.innerText = "Tizimga Kirish";
      }
    }

    async function handleRegisterSubmit(e) {
      e.preventDefault();
      const email = document.getElementById('regEmail').value.trim();
      const username = document.getElementById('regUsername').value.trim();
      const password = document.getElementById('regPassword').value;
      const btn = document.getElementById('btnRegisterSubmit');
      btn.disabled = true;
      btn.innerText = "Yaratilmoqda...";

      try {
        const res = await fetch('/api/auth/register/', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ email, username, password })
        });
        const data = await res.json();
        if (res.ok) {
          showToast("Hisob yaratildi! Kirilmoqda...", 'success');
          // Auto login
          const logRes = await fetch('/api/auth/login/', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ email, password })
          });
          const logData = await logRes.json();
          if (logRes.ok) {
            localStorage.setItem('access_token', logData.access);
            localStorage.setItem('refresh_token', logData.refresh);
            closeAuthModal();
            await checkAuth();
          } else {
            switchAuthTab('login');
          }
        } else {
          const err = data.email ? data.email[0] : (data.detail || "Ro'yxatdan o'tishda xatolik.");
          showToast(err, 'error');
        }
      } catch (err) {
        showToast("Server bilan bog'lanishda xatolik.", 'error');
      } finally {
        btn.disabled = false;
        btn.innerText = "Ro'yxatdan O'tish";
      }
    }

    // BOOKS DATA FETCHING & RENDERING
    async function loadBooks() {
      try {
        const token = localStorage.getItem('access_token');
        const headers = token ? { 'Authorization': 'Bearer ' + token } : {};
        const res = await fetch('/api/books/', { headers });
        if (res.ok) {
          allBooks = await res.json();
          updateMetrics();
          renderGenrePills();
          renderBooks();
        }
      } catch (err) {
        console.error("Books loading error:", err);
      }
    }

    function updateMetrics() {
      document.getElementById('statTotalBooks').innerText = allBooks.length;
      const audioCount = allBooks.filter(b => b.has_audio || b.audio_file || b.audiobook_url).length;
      document.getElementById('statTotalAudio').innerText = audioCount;

      const genresSet = new Set(allBooks.map(b => b.genre).filter(Boolean));
      document.getElementById('statTotalGenres').innerText = genresSet.size;
    }

    function renderGenrePills() {
      const container = document.getElementById('genrePillsContainer');
      const genresSet = new Set(allBooks.map(b => b.genre).filter(Boolean));

      let html = `<button class="genre-pill ${currentFilterGenre === 'all' ? 'active' : ''}" onclick="filterByGenre('all', this)">Barchasi</button>`;
      genresSet.forEach(genre => {
        html += `<button class="genre-pill ${currentFilterGenre === genre ? 'active' : ''}" onclick="filterByGenre('${genre}', this)">${genre}</button>`;
      });
      container.innerHTML = html;
    }

    function filterByGenre(genre, btn) {
      currentFilterGenre = genre;
      document.querySelectorAll('.genre-pill').forEach(p => p.classList.remove('active'));
      if (btn) btn.classList.add('active');
      renderBooks();
    }

    function toggleAudioOnlyFilter() {
      filterAudioOnly = !filterAudioOnly;
      const btn = document.getElementById('audioFilterToggle');
      if (filterAudioOnly) {
        btn.classList.add('active');
      } else {
        btn.classList.remove('active');
      }
      renderBooks();
    }

    function handleSearch() {
      renderBooks();
    }

    function renderBooks() {
      const grid = document.getElementById('booksGrid');
      const searchQuery = document.getElementById('searchInput').value.trim().toLowerCase();
      const isAdmin = currentUser && (currentUser.is_staff || currentUser.is_superuser);

      let filtered = allBooks.filter(b => {
        const matchGenre = currentFilterGenre === 'all' || b.genre === currentFilterGenre;
        const hasAudio = Boolean(b.has_audio || b.audio_file || b.audiobook_url);
        const matchAudio = !filterAudioOnly || hasAudio;
        const matchSearch = !searchQuery || 
          (b.title && b.title.toLowerCase().includes(searchQuery)) ||
          (b.author && b.author.toLowerCase().includes(searchQuery)) ||
          (b.genre && b.genre.toLowerCase().includes(searchQuery)) ||
          (b.description && b.description.toLowerCase().includes(searchQuery));
        return matchGenre && matchAudio && matchSearch;
      });

      document.getElementById('catalogCountText').innerText = `Mavjud Kitoblar (${filtered.length} ta)`;

      if (filtered.length === 0) {
        grid.innerHTML = `
          <div style="grid-column: 1/-1; text-align: center; padding: 3rem; color: var(--text-muted);">
            <i class="fa-solid fa-book-open" style="font-size: 3rem; margin-bottom: 1rem; opacity: 0.5;"></i>
            <h3>Hech qanday kitob topilmadi</h3>
            <p style="font-size: 0.85rem; margin-top: 0.5rem;">Qidiruv yoki filtrlarni o'zgartirib ko'ring.</p>
          </div>
        `;
        return;
      }

      grid.innerHTML = filtered.map(book => {
        const hasAudio = Boolean(book.has_audio || book.audio_file || book.audiobook_url);
        const hasPdf = Boolean(book.file);
        const audioUrl = book.audio_file || book.audiobook_url || '';
        const pdfUrl = book.file || '';

        const audioBadge = hasAudio 
          ? `<span class="badge-tag audio"><i class="fa-solid fa-volume-high"></i> Audio</span>` 
          : '';
        const pdfBadge = hasPdf 
          ? `<span class="badge-tag pdf"><i class="fa-solid fa-file-pdf"></i> PDF</span>` 
          : '';

        // Admin action buttons (strictly for admin only)
        const adminButtons = isAdmin ? `
          <button class="btn-admin-action btn-add-audio-admin" title="Audio kitob biriktirish" onclick="openUploadAudioModal(${book.id}, '${escapeHtml(book.title)}')">
            <i class="fa-solid fa-file-audio"></i>
          </button>
          <button class="btn-admin-action btn-delete-admin" title="Kitobni o'chirish" onclick="deleteBook(${book.id}, '${escapeHtml(book.title)}')">
            <i class="fa-solid fa-trash-can"></i>
          </button>
        ` : '';

        return `
          <div class="book-card" id="bookCard-${book.id}">
            <div class="book-card-banner">
              <div class="book-icon-badge">
                <i class="fa-solid fa-book-bookmark"></i>
              </div>
              <div class="book-card-badges">
                ${audioBadge}
                ${pdfBadge}
              </div>
            </div>

            <div class="book-card-body">
              <h3 class="book-title" title="${escapeHtml(book.title)}">${escapeHtml(book.title)}</h3>
              <div class="book-author">
                <i class="fa-solid fa-feather-pointed" style="color:var(--primary);"></i>
                <span>${escapeHtml(book.author || 'Noma\'lum')}</span>
              </div>
              <div class="book-genre-label">${escapeHtml(book.genre || 'Adabiyot')}</div>
              <p class="book-desc">${escapeHtml(book.description || 'Ushbu kitob tavsifi tez orada to\'ldiriladi.')}</p>

              <div class="book-card-actions">
                <button class="btn-card btn-read" onclick="openReaderModal(${book.id})">
                  <i class="fa-solid fa-book-open"></i> O'qish
                </button>
                <button class="btn-card btn-listen" onclick="handleBookListen(${book.id})">
                  <i class="fa-solid fa-headphones"></i> Tinglash
                </button>
                ${adminButtons}
              </div>
            </div>
          </div>
        `;
      }).join('');
    }

    function escapeHtml(text) {
      if (!text) return '';
      return text.replace(/[&<>"']/g, function(m) {
        return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m];
      });
    }

    // AUDIO PLAYER LOGIC
    function handleBookListen(bookId) {
      const book = allBooks.find(b => b.id === bookId);
      if (!book) return;

      const audioUrl = book.audio_file || book.audiobook_url;
      if (audioUrl) {
        startAudioPlayback(book, audioUrl);
      } else {
        // Fallback: browser text-to-speech
        showToast(`"${book.title}" audio fayli mavjud emas. Matn ovozli o'qilmoqda...`, 'info');
        speakText(`${book.title}. Muallif: ${book.author}. ${book.description || ''}`);
      }
    }

    function startAudioPlayback(book, audioUrl) {
      if (window.speechSynthesis && window.speechSynthesis.speaking) {
        window.speechSynthesis.cancel();
      }

      document.getElementById('playerBookTitle').innerText = book.title;
      document.getElementById('playerBookAuthor').innerText = book.author || 'Audio Kitob';
      document.getElementById('audioPlayerBar').style.display = 'flex';

      nativeAudio.src = audioUrl;
      nativeAudio.playbackRate = currentPlaybackRate;
      nativeAudio.play().then(() => {
        updatePlayPauseButton(true);
      }).catch(err => {
        console.warn("Autoplay blocked or stream error:", err);
        updatePlayPauseButton(false);
      });
    }

    function setupAudioPlayerEvents() {
      nativeAudio.addEventListener('timeupdate', () => {
        const cur = nativeAudio.currentTime;
        const dur = nativeAudio.duration;
        document.getElementById('playerCurrentTime').innerText = formatTime(cur);
        if (dur && !isNaN(dur)) {
          document.getElementById('playerDuration').innerText = formatTime(dur);
          const pct = (cur / dur) * 100;
          document.getElementById('playerProgressFilled').style.width = pct + '%';
        }
      });

      nativeAudio.addEventListener('ended', () => {
        updatePlayPauseButton(false);
        document.getElementById('playerProgressFilled').style.width = '0%';
      });

      nativeAudio.addEventListener('pause', () => updatePlayPauseButton(false));
      nativeAudio.addEventListener('play', () => updatePlayPauseButton(true));
    }

    function togglePlayPause() {
      if (nativeAudio.paused) {
        nativeAudio.play();
      } else {
        nativeAudio.pause();
      }
    }

    function updatePlayPauseButton(isPlaying) {
      const icon = document.getElementById('playPauseIcon');
      if (isPlaying) {
        icon.className = 'fa-solid fa-pause';
      } else {
        icon.className = 'fa-solid fa-play';
      }
    }

    function seekAudio(seconds) {
      nativeAudio.currentTime = Math.max(0, Math.min(nativeAudio.duration || 0, nativeAudio.currentTime + seconds));
    }

    function handleSeekbarClick(e) {
      const bar = document.getElementById('playerProgressBar');
      const rect = bar.getBoundingClientRect();
      const clickX = e.clientX - rect.left;
      const width = rect.width;
      if (nativeAudio.duration) {
        nativeAudio.currentTime = (clickX / width) * nativeAudio.duration;
      }
    }

    function cyclePlaybackRate() {
      const curIdx = playbackRates.indexOf(currentPlaybackRate);
      const nextIdx = (curIdx + 1) % playbackRates.length;
      currentPlaybackRate = playbackRates[nextIdx];
      nativeAudio.playbackRate = currentPlaybackRate;
      document.getElementById('btnPlaybackRate').innerText = currentPlaybackRate + 'x';
    }

    function setVolume(val) {
      nativeAudio.volume = parseFloat(val);
      const icon = document.getElementById('playerVolumeIcon');
      if (nativeAudio.volume === 0) icon.className = 'fa-solid fa-volume-xmark';
      else if (nativeAudio.volume < 0.5) icon.className = 'fa-solid fa-volume-low';
      else icon.className = 'fa-solid fa-volume-high';
    }

    function toggleMute() {
      nativeAudio.muted = !nativeAudio.muted;
      document.getElementById('playerVolumeIcon').className = nativeAudio.muted 
        ? 'fa-solid fa-volume-xmark' 
        : 'fa-solid fa-volume-high';
    }

    function closeAudioPlayer() {
      nativeAudio.pause();
      nativeAudio.src = '';
      document.getElementById('audioPlayerBar').style.display = 'none';
    }

    function formatTime(sec) {
      if (!sec || isNaN(sec)) return '00:00';
      const m = Math.floor(sec / 60);
      const s = Math.floor(sec % 60);
      return (m < 10 ? '0' + m : m) + ':' + (s < 10 ? '0' + s : s);
    }

    function speakText(text) {
      if (window.speechSynthesis) {
        if (window.speechSynthesis.speaking) window.speechSynthesis.cancel();
        const utter = new SpeechSynthesisUtterance(text);
        utter.lang = 'uz-UZ';
        utter.rate = 0.95;
        window.speechSynthesis.speak(utter);
      }
    }

    // READER MODAL
    function openReaderModal(bookId) {
      const book = allBooks.find(b => b.id === bookId);
      if (!book) return;

      document.getElementById('readerBookTitle').innerText = book.title;
      const frame = document.getElementById('readerPdfFrame');
      const textContainer = document.getElementById('readerTextContainer');

      if (book.file) {
        frame.src = book.file;
        switchReaderTab('pdf');
      } else {
        switchReaderTab('text');
      }

      textContainer.innerText = book.content || (book.description || "Ushbu kitobning matnli varianti hozircha mavjud emas.");
      document.getElementById('readerModal').style.display = 'flex';
    }

    function switchReaderTab(tab) {
      const btnPdf = document.getElementById('btnTabPdf');
      const btnText = document.getElementById('btnTabText');
      const frame = document.getElementById('readerPdfFrame');
      const text = document.getElementById('readerTextContainer');

      if (tab === 'pdf') {
        btnPdf.classList.add('active');
        btnText.classList.remove('active');
        frame.style.display = 'block';
        text.style.display = 'none';
      } else {
        btnText.classList.add('active');
        btnPdf.classList.remove('active');
        frame.style.display = 'none';
        text.style.display = 'block';
      }
    }

    function closeReaderModal() {
      document.getElementById('readerModal').style.display = 'none';
      document.getElementById('readerPdfFrame').src = '';
    }

    // ADMIN: ADD BOOK MODAL
    function openAddBookModal() {
      document.getElementById('formAddBook').reset();
      document.getElementById('addBookModal').style.display = 'flex';
    }

    function closeAddBookModal() {
      document.getElementById('addBookModal').style.display = 'none';
    }

    async function handleAddBookSubmit(e) {
      e.preventDefault();
      const token = localStorage.getItem('access_token');
      if (!token) {
        showToast("Faqat administrator kitob qo'sha oladi. Iltimos kiring.", 'error');
        return;
      }

      const title = document.getElementById('newBookTitle').value.trim();
      const author = document.getElementById('newBookAuthor').value.trim() || "Noma'lum";
      const genre = document.getElementById('newBookGenre').value.trim() || "Badiiy";
      const description = document.getElementById('newBookDesc').value.trim();
      const pdfFile = document.getElementById('newBookPdf').files[0];
      const audioFile = document.getElementById('newBookAudio').files[0];
      const audioUrl = document.getElementById('newBookAudioUrl').value.trim();

      const formData = new FormData();
      formData.append('title', title);
      formData.append('author', author);
      formData.append('genre', genre);
      formData.append('description', description);
      if (pdfFile) formData.append('file', pdfFile);
      if (audioFile) formData.append('audio_file', audioFile);
      if (audioUrl) formData.append('audiobook_url', audioUrl);

      const btn = document.getElementById('btnSaveBook');
      btn.disabled = true;
      btn.innerText = "Yuklanmoqda...";

      try {
        const res = await fetch('/api/books/', {
          method: 'POST',
          headers: { 'Authorization': 'Bearer ' + token },
          body: formData
        });
        if (res.ok) {
          showToast(`"${title}" kitobi muvaffaqiyatli qo'shildi!`, 'success');
          closeAddBookModal();
          await loadBooks();
        } else {
          const data = await res.json();
          showToast(data.detail || "Kitob qo'shishda xatolik yuz berdi.", 'error');
        }
      } catch (err) {
        showToast("Server xatosi.", 'error');
      } finally {
        btn.disabled = false;
        btn.innerText = "Kitobni Saqlash";
      }
    }

    // ADMIN: UPLOAD AUDIO TO EXISTING BOOK
    function openUploadAudioModal(bookId, bookTitle) {
      document.getElementById('audioTargetBookId').value = bookId;
      document.getElementById('audioTargetBookTitle').innerText = bookTitle;
      document.getElementById('formUploadAudio').reset();
      document.getElementById('uploadAudioModal').style.display = 'flex';
    }

    function closeUploadAudioModal() {
      document.getElementById('uploadAudioModal').style.display = 'none';
    }

    async function handleAudioUploadSubmit(e) {
      e.preventDefault();
      const token = localStorage.getItem('access_token');
      const bookId = document.getElementById('audioTargetBookId').value;
      const audioFile = document.getElementById('audioUploadFile').files[0];
      const audioUrl = document.getElementById('audioUploadUrl').value.trim();

      if (!audioFile && !audioUrl) {
        showToast("Iltimos, audio fayl tanlang yoki havola kiriting.", 'error');
        return;
      }

      const formData = new FormData();
      if (audioFile) formData.append('audio_file', audioFile);
      if (audioUrl) formData.append('audiobook_url', audioUrl);

      const btn = document.getElementById('btnSaveAudio');
      btn.disabled = true;
      btn.innerText = "Yuklanmoqda...";

      try {
        const res = await fetch(`/api/books/${bookId}/upload_audio/`, {
          method: 'POST',
          headers: { 'Authorization': 'Bearer ' + token },
          body: formData
        });
        if (res.ok) {
          showToast("Audio kitob muvaffaqiyatli biriktirildi!", 'success');
          closeUploadAudioModal();
          await loadBooks();
        } else {
          const data = await res.json();
          showToast(data.detail || data.non_field_errors?.[0] || "Yuklashda xatolik yuz berdi.", 'error');
        }
      } catch (err) {
        showToast("Server bilan bog'lanishda xatolik.", 'error');
      } finally {
        btn.disabled = false;
        btn.innerText = "Audio Kitobni Saqlash";
      }
    }

    // ADMIN: DELETE BOOK
    async function deleteBook(bookId, title) {
      if (!confirm(`"${title}" nomli kitobni o'chirishni tasdiqlaysizmi?\nBu amalni qaytarib bo'lmaydi!`)) {
        return;
      }

      const token = localStorage.getItem('access_token');
      try {
        const res = await fetch(`/api/books/${bookId}/`, {
          method: 'DELETE',
          headers: { 'Authorization': 'Bearer ' + token }
        });
        if (res.status === 204 || res.ok) {
          showToast(`"${title}" kitobi o'chirildi!`, 'success');
          await loadBooks();
        } else if (res.status === 403) {
          showToast("Faqat administrator kitobni o'chirish huquqiga ega!", 'error');
        } else {
          showToast("O'chirishda xatolik yuz berdi.", 'error');
        }
      } catch (err) {
        showToast("Server bilan bog'lanishda xatolik.", 'error');
      }
    }

    // ADMIN: QUICK PDF / ZIP UPLOADS
    async function handleQuickUpload(input, type) {
      const file = input.files[0];
      if (!file) return;

      const token = localStorage.getItem('access_token');
      if (!token) {
        showToast("Faqat admin yuklay oladi.", 'error');
        return;
      }

      const formData = new FormData();
      const endpoint = type === 'pdf' ? '/api/upload-pdf/' : '/api/upload-zip/';
      const field = type === 'pdf' ? 'pdffile' : 'zipfile';
      formData.append(field, file);

      showToast(`${file.name} yuklanmoqda va qayta ishlanmoqda...`, 'info');

      try {
        const res = await fetch(endpoint, {
          method: 'POST',
          headers: { 'Authorization': 'Bearer ' + token },
          body: formData
        });
        const data = await res.json();
        if (res.ok) {
          showToast(data.message || `Fayl muvaffaqiyatli yuklandi va kitoblar qo'shildi!`, 'success');
          await loadBooks();
        } else {
          showToast(data.detail || "Yuklashda xatolik.", 'error');
        }
      } catch (err) {
        showToast("Server xatosi.", 'error');
      } finally {
        input.value = '';
      }
    }

    // AI CHATBOT FUNCTIONALITY
    function toggleChat() {
      const win = document.getElementById('chatWindow');
      win.classList.toggle('active');
      if (win.classList.contains('active')) {
        document.getElementById('chatInput').focus();
      }
    }

    function handleChatKeyPress(e) {
      if (e.key === 'Enter') {
        sendMessage();
      }
    }

    function askQuickPrompt(text) {
      document.getElementById('chatInput').value = text;
      sendMessage();
    }

    async function sendMessage() {
      const input = document.getElementById('chatInput');
      const message = input.value.trim();
      if (!message) return;

      const chatMessages = document.getElementById('chatMessages');

      // Add user message bubble
      const userBubble = document.createElement('div');
      userBubble.className = 'chat-bubble user';
      userBubble.innerText = message;
      chatMessages.appendChild(userBubble);
      input.value = '';

      // Add loading bot bubble
      const loadingBubble = document.createElement('div');
      loadingBubble.className = 'chat-bubble bot';
      loadingBubble.id = 'botLoadingBubble';
      loadingBubble.innerHTML = '<i class="fa-solid fa-ellipsis fa-fade"></i> AI o\'ylamoqda...';
      chatMessages.appendChild(loadingBubble);
      chatMessages.scrollTop = chatMessages.scrollHeight;

      const token = localStorage.getItem('access_token');
      const headers = { 'Content-Type': 'application/json' };
      if (token) headers['Authorization'] = 'Bearer ' + token;

      try {
        const res = await fetch('/api/chat/', {
          method: 'POST',
          headers: headers,
          body: JSON.stringify({ message: message })
        });
        const data = await res.json();

        loadingBubble.id = '';
        if (res.ok && data.reply) {
          // Format markdown bold & linebreaks
          let formattedReply = escapeHtml(data.reply)
            .replace(/\*\*(.*?)\*\*/g, '<b>$1</b>')
            .replace(/\n/g, '<br>');
          loadingBubble.innerHTML = formattedReply;
        } else {
          loadingBubble.innerHTML = "Kechirasiz, javob olishda xatolik yuz berdi.";
        }
      } catch (err) {
        loadingBubble.id = '';
        loadingBubble.innerHTML = "Server bilan bog'lanishda xatolik yuz berdi.";
      }

      chatMessages.scrollTop = chatMessages.scrollHeight;
    }
  </script>
</body>
</html>

